def split_csv(line):
    if line == "":
        return [""]

    fields = []
    i = 0
    n = len(line)

    while i < n:
        # Start of a new field
        if line[i] == '"':
            # Quoted field
            field = ""
            i += 1  # Skip opening quote
            while i < n:
                if line[i] == '"':
                    # Check what comes after the quote
                    if i + 1 < n and line[i + 1] == '"':
                        # Doubled quote - add one quote to field
                        field += '"'
                        i += 2
                    else:
                        # Closing quote
                        i += 1
                        # Check what follows: must be comma or end of line
                        if i < n and line[i] != ',':
                            return None
                        if i < n:
                            i += 1  # Skip the comma
                        fields.append(field)
                        break
                else:
                    field += line[i]
                    i += 1
            else:
                # Reached end of line without closing quote
                return None
        else:
            # Unquoted field - runs to next comma or end of line
            field = ""
            while i < n and line[i] != ',':
                if line[i] == '"':
                    # Unquoted field cannot contain quotes
                    return None
                field += line[i]
                i += 1

            fields.append(field)
            if i < n:
                i += 1  # Skip the comma

    return fields

